function getState(name){return process.env[`STATE_${name}`]||""}function warning(message){issue("warning",message)}function issue(command,message,properties={}){const fields=Object.entries(properties).map(([name,value])=>`${name}=${escapeProperty(value)}`).join(",");console.log(`::${command}${fields?` ${fields}`:""}::${escapeData(message)}`)}function escapeData(value){return String(value).replaceAll("%","%25").replaceAll("\r","%0D").replaceAll("\n","%0A")}function escapeProperty(value){return escapeData(value).replaceAll(":","%3A").replaceAll(",","%2C")}import{tmpdir}from"node:os";import{rm}from"node:fs/promises";import{basename,join,relative,resolve}from"node:path";async function stopForward(pid,timeoutMilliseconds=3e3){if(!Number.isSafeInteger(pid)||pid<2||!isAlive(pid)){return}signalProcessGroup(pid,"SIGTERM");const deadline=Date.now()+timeoutMilliseconds;while(Date.now()<deadline){if(!isAlive(pid)){return}await delay(100)}signalProcessGroup(pid,"SIGKILL")}async function removeWorkDir(workDir,temporaryRoot){if(!workDir){return}const resolvedDirectory=resolve(workDir);const resolvedRoot=resolve(temporaryRoot);const pathFromRoot=relative(resolvedRoot,resolvedDirectory);if(!pathFromRoot||pathFromRoot.startsWith("..")||basename(resolvedDirectory).startsWith("platformd-port-forward-")===false){throw new Error("refusing to remove an unexpected action work directory")}await rm(resolvedDirectory,{force:true,recursive:true})}function isAlive(pid){try{process.kill(pid,0);return true}catch(error){if(error&&typeof error==="object"&&"code"in error&&error.code==="EPERM"){return true}return false}}function signalProcessGroup(pid,signal){try{process.kill(-pid,signal)}catch(error){if(!(error&&typeof error==="object"&&"code"in error&&error.code==="ESRCH")){throw error}}}function delay(milliseconds){return new Promise(resolveDelay=>setTimeout(resolveDelay,milliseconds))}async function run(){const pidValue=getState("forward-pid");const workDir=getState("work-dir");try{if(pidValue){await stopForward(Number(pidValue))}if(workDir){await removeWorkDir(workDir,process.env.RUNNER_TEMP||tmpdir())}}catch(error){warning(`Unable to clean up platformd-forward: ${error instanceof Error?error.message:String(error)}`)}}void run();
